var sddpDeviceMod = require('sddp_device.js');
var SddpDevice = sddpDeviceMod.SddpDevice;

// class
function SddpPacket()
{
  // Parse
  this.packetType = SddpPacket.PacketType.UNKNOWN;
  this.method = "";
  this.argument = "";
  this.statusCode = "";
  this.reason = "";
  this.version = "";
  this.from = "";
  this.host = "";
  this.tran = "";
  this.maxAge = "";
  this.timeout = "";
  this.primaryProxy = "";
  this.proxies = "";
  this.manufacturer = "";
  this.model = "";
  this.driver = "";
  this.type = "";
  this.body = "";
}

// static const
SddpPacket.PacketType = {UNKNOWN:0, REQUEST:1, RESPONSE:2};
SddpPacket.SDDP_VERSION = "1.0";
SddpPacket.SDDP_PORT = 1902;

var createPacketResponse = function(sddpPacket, device) {
  // Copy the required fields
  sddpPacket.packetType = SddpPacket.PacketType.RESPONSE;
  sddpPacket.from = device.getAddress() + ":" + SddpPacket.SDDP_PORT;
  sddpPacket.host = device.getHost();
  sddpPacket.tran = device.getTran();
  sddpPacket.maxAge = String(device.getMaxAge());
  sddpPacket.type = device.getProductName();
  sddpPacket.primaryProxy = device.getPrimaryProxy();
  sddpPacket.proxies = device.getProxies();
  sddpPacket.manufacturer = device.getManufacturer();
  sddpPacket.model = device.getModel();
  sddpPacket.driver = device.getDriver();
  // Create packet
  var packet = "SDDP/" + SddpPacket.SDDP_VERSION + " 200 OK\r\n";
  packet = packet + "From: \"" + sddpPacket.from + "\"\r\n";
  packet = packet + "Host: \"" + sddpPacket.host + "\"\r\n";
  packet = packet + "Tran: " + sddpPacket.tran + "\r\n";
  packet = packet + "Max-Age: " + sddpPacket.maxAge + "\r\n";
  packet = packet + "Type: \"" + sddpPacket.type + "\"\r\n";
  packet = packet + "Primary-Proxy: \"" + sddpPacket.primaryProxy + "\"\r\n";
  packet = packet + "Proxies: \"" + sddpPacket.proxies + "\"\r\n";
  packet = packet + "Manufacturer: \"" + sddpPacket.manufacturer + "\"\r\n";
  packet = packet + "Model: \"" + sddpPacket.model + "\"\r\n";
  packet = packet + "Driver: \"" + sddpPacket.driver + "\"\r\n";
  return packet;
};

var createPacketAlive = function(sddpPacket, device) {
  // Copy the required fields
  sddpPacket.packetType = SddpPacket.PacketType.REQUEST;
  sddpPacket.from = device.getAddress() + ":" + SddpPacket.SDDP_PORT;
  sddpPacket.host = device.getHost();
  sddpPacket.maxAge = String(device.getMaxAge());
  sddpPacket.type = device.getProductName();
  sddpPacket.primaryProxy = device.getPrimaryProxy();
  sddpPacket.proxies = device.getProxies();
  sddpPacket.manufacturer = device.getManufacturer();
  sddpPacket.model = device.getModel();
  sddpPacket.driver = device.getDriver();
  // Create packet
  var packet = "NOTIFY ALIVE SDDP/" + SddpPacket.SDDP_VERSION + "\r\n";
  packet = packet + "From: \"" + sddpPacket.from + "\"\r\n";
  packet = packet + "Host: \"" + sddpPacket.host + "\"\r\n";
  packet = packet + "Max-Age: " + sddpPacket.maxAge + "\r\n";
  packet = packet + "Type: \"" + sddpPacket.type + "\"\r\n";
  packet = packet + "Primary-Proxy: \"" + sddpPacket.primaryProxy + "\"\r\n";
  packet = packet + "Proxies: \"" + sddpPacket.proxies + "\"\r\n";
  packet = packet + "Manufacturer: \"" + sddpPacket.manufacturer + "\"\r\n";
  packet = packet + "Model: \"" + sddpPacket.model + "\"\r\n";
  packet = packet + "Driver: \"" + sddpPacket.driver + "\"\r\n";
  return packet;
};

var createPacketOffLine = function(sddpPacket, device) {
  // Copy the required fields
  sddpPacket.packetType = SddpPacket.PacketType.REQUEST;
  sddpPacket.from = device.getAddress() + ":" + SddpPacket.SDDP_PORT;
  sddpPacket.host = device.getHost();
  sddpPacket.type = device.getProductName();
  // Create packet
  var packet = "NOTIFY OFFLINE SDDP/" + SddpPacket.SDDP_VERSION + "\r\n";
  packet = packet + "From: \"" + sddpPacket.from + "\"\r\n";
  packet = packet + "Host: \"" + sddpPacket.host + "\"\r\n";
  packet = packet + "Type: \"" + sddpPacket.type + "\"\r\n";
  return packet;
};

var createPacketIdentify = function(sddpPacket, device) {
  // Copy the required fields
  sddpPacket.packetType = SddpPacket.PacketType.REQUEST;
  sddpPacket.from = device.getAddress() + ":" + SddpPacket.SDDP_PORT;
  sddpPacket.host = device.getHost();
  sddpPacket.type = device.getProductName();
  sddpPacket.primaryProxy = device.getPrimaryProxy();
  sddpPacket.proxies = device.getProxies();
  sddpPacket.manufacturer = device.getManufacturer();
  sddpPacket.model = device.getModel();
  sddpPacket.driver = device.getDriver();
  // Create packet
  var packet = "NOTIFY IDENTIFY SDDP/" + SddpPacket.SDDP_VERSION + "\r\n";
  packet = packet + "From: \"" + sddpPacket.from + "\"\r\n";
  packet = packet + "Host: \"" + sddpPacket.host + "\"\r\n";
  packet = packet + "Type: \"" + sddpPacket.type + "\"\r\n";
  packet = packet + "Primary-Proxy: \"" + sddpPacket.primaryProxy + "\"\r\n";
  packet = packet + "Proxies: \"" + sddpPacket.proxies + "\"\r\n";
  packet = packet + "Manufacturer: \"" + sddpPacket.manufacturer + "\"\r\n";
  packet = packet + "Model: \"" + sddpPacket.model + "\"\r\n";
  packet = packet + "Driver: \"" + sddpPacket.driver + "\"\r\n";
  return packet;
};

